<?php
require_once 'auth_check.php'; require_once __DIR__ . '/app/partials.php'; $conn=getDBConnection();
$byFoundation=$conn->query("SELECT f.fname,COUNT(*) donations,COALESCE(SUM(CASE WHEN d.payment_status='Complete' THEN d.amount END),0) total FROM foundations f LEFT JOIN donations d ON d.foundation_id=f.fid GROUP BY f.fid,f.fname ORDER BY total DESC");
$byMethod=$conn->query("SELECT payment_method,COUNT(*) donations,COALESCE(SUM(CASE WHEN payment_status='Complete' THEN amount END),0) total FROM donations GROUP BY payment_method ORDER BY total DESC");
$monthly=$conn->query("SELECT DATE_FORMAT(created_at,'%Y-%m') month,COUNT(*) donations,COALESCE(SUM(CASE WHEN payment_status='Complete' THEN amount END),0) total FROM donations GROUP BY DATE_FORMAT(created_at,'%Y-%m') ORDER BY month DESC LIMIT 12");
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reports</title><link rel="stylesheet" href="css/addashb.css"><style>.main-content{margin-left:250px;padding:24px}.report{background:#fff;padding:18px;margin:16px 0;overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:10px;border:1px solid #ddd;text-align:left}</style></head><body><div class="dashboard-container"><?php render_admin_sidebar('reports'); ?><main class="main-content"><h1>Donation Reports</h1><p>Only completed donations contribute to monetary totals.</p><?php $sets=['By foundation'=>$byFoundation,'By payment method'=>$byMethod,'Monthly donations'=>$monthly]; foreach($sets as $title=>$rows): ?><section class="report"><h2><?=e($title)?></h2><table><tr><th>Group</th><th>Donations</th><th>Completed total (MMK)</th></tr><?php while($row=$rows->fetch_assoc()): $label=$row['fname']??($row['payment_method']??$row['month']); ?><tr><td><?=e($label)?></td><td><?= (int)$row['donations']?></td><td><?=number_format((float)$row['total'],2)?></td></tr><?php endwhile;?></table></section><?php endforeach;?></main></div></body></html><?php $conn->close(); ?>
